use std::fs;
use std::path::PathBuf;

fn main() {
    build_info::emit_build_env();

    // The components catalog is generated by `scripts/build-bundles.mjs` and
    // landed at `apps/shipd/assets/sui-custom-elements.json`. We `include_str!`
    // it from `components_catalog.rs`, so cargo needs to know to rebuild when
    // that file changes — `include_str!` does not declare a build dep on its
    // own. We also seed an empty placeholder on fresh clones where the node
    // bundle script hasn't run yet, mirroring `apps/shipd/build.rs`.
    let manifest_dir: PathBuf = std::env::var_os("CARGO_MANIFEST_DIR")
        .expect("CARGO_MANIFEST_DIR")
        .into();
    let catalog_path = manifest_dir
        .join("..")
        .join("shipd")
        .join("assets")
        .join("sui-custom-elements.json");
    println!(
        "cargo:rerun-if-changed={}",
        catalog_path.display()
    );
    if !catalog_path.exists() {
        if let Some(parent) = catalog_path.parent() {
            if let Err(e) = fs::create_dir_all(parent) {
                panic!("build.rs: mkdir {parent:?}: {e}");
            }
        }
        if let Err(e) = fs::write(&catalog_path, "{}") {
            panic!("build.rs: write placeholder {catalog_path:?}: {e}");
        }
    }
}
